async function file(path,ref=branch){return api(`/repos/${repository}/contents/${path}?ref=${encodeURIComponent(ref)}`,{headers:{Accept:'application/vnd.github.raw+json'}});}
function lock(value){busy=value;for(const id of ['apply','ignore','collect','organize','refresh'])$(id).disabled=value;}
function draft(c){if(!drafts.has(c.id))drafts.set(c.id,{id:c.id,title:c.title,date:c.publishedDateKST,dateBasis:c.sourceKind==='youtube'?'video-published':'article-published',type:c.suggestedType in TYPES?c.suggestedType:'etc',members:(c.members||[]).filter(x=>MEMBERS.includes(x)),program:'',eventState:'',url:c.url,label:c.publisher||'원문 자료',note:'',targetId:c.recommendedTargetId||((c.relatedRecords||[]).length===1&&c.relatedRecords[0].strong?c.relatedRecords[0].id:''),mode:c.recommendedTargetId||((c.relatedRecords||[]).length===1&&c.relatedRecords[0].strong)?'link':'new'});return drafts.get(c.id);}
